import os

def get_file_ext(path):
    name, ext = os.path.splitext(path)
    return ext

def get_files(path):
    files = []
    for f in os.listdir(path):
        full_path = os.path.join(path, f)
        if os.path.isfile(full_path):
            files.append(full_path)
    return files

def tar_files(files, tar_file):
    tar = tarfile.open(tar_file, 'w')
    for f in files:
        tar.add(f)
    tar.close()

if __name__ == '__main__':
    path = '../'
    tar_file = 'files.tar'
    files = get_files(path)

    tar_files(files, tar_file)

    print(f'Created tar archive {tar_file} containing:')
    for f in files:
        ext = get_file_ext(f)
        print(f'{f} ({ext})')

